[{"order":1,"type":"heading","text":"Performance Optimization and Garbage Collection in NativeScript"},{"order":2,"type":"paragraph","text":"Building high-performance mobile applications with NativeScript requires a deep understanding of memory management, bridge communication, and garbage collection mechanisms. Because NativeScript bridges JavaScript with native Android and iOS APIs, memory leaks can occur on both sides of the bridge if resources are not properly released."},{"order":3,"type":"subheading","text":"Understanding Garbage Collection in NativeScript"},{"order":4,"type":"paragraph","text":"NativeScript runs your JavaScript code inside a JavaScript engine (V8 on Android, JavaScriptCore on iOS). Each JavaScript object often has a corresponding native object counterpart. The JavaScript garbage collector (GC) automatically frees memory when objects are no longer reachable. However, circular references between JavaScript and native objects can prevent the GC from reclaiming memory, leading to memory leaks."},{"order":5,"type":"subheading","text":"Common Causes of Memory Leaks"},{"order":6,"type":"bullet_point","text":"Dangling event listeners that are not removed when a page or component is destroyed."},{"order":7,"type":"bullet_point","text":"Global variables holding strong references to UI components or native views."},{"order":8,"type":"bullet_point","text":"Retaining references to native Android activities or iOS view controllers inside JavaScript closures."},{"order":9,"type":"subheading","text":"Best Practices for Memory Management"},{"order":10,"type":"paragraph","text":"To ensure your NativeScript app remains responsive and avoids out-of-memory crashes, follow these optimization strategies:"},{"order":11,"type":"bullet_point","text":"Always unsubscribe from events and observables in the unloaded lifecycle hook of your pages or components."},{"order":12,"type":"bullet_point","text":"Use weak references when passing callbacks or handling native objects that outlive your UI components."},{"order":13,"type":"subheading","text":"Example: Cleaning Up Event Listeners"},{"order":14,"type":"code","text":"import { EventData, Page } from '@nativescript/core';

export function onLoaded(args: EventData) {
    const page = <Page>args.object;
    page.on('navigatingFrom', onNavigatingFrom);
}

function onNavigatingFrom(args: EventData) {
    const page = <Page>args.object;
    // Clean up event listeners to allow garbage collection
    page.off('navigatingFrom', onNavigatingFrom);
}"},{"order":15,"type":"subheading","text":"Optimizing ListView Performance"},{"order":16,"type":"paragraph","text":"Lists are frequent bottlenecks in mobile applications. In NativeScript, the ListView component recycles item views to optimize memory usage and rendering speed. Ensure that your item templates are lightweight and avoid complex nested layouts when a simpler layout suffices."},{"order":17,"type":"code","text":"<ListView items="{{ myItems }}" itemLoading="{{ onItemLoading }}">
    <ListView.itemTemplate>
        <GridLayout rows="auto" columns="*, auto">
            <Label text="{{ title }}" col="0" />
            <Button text="Action" col="1" tap="{{ onActionTap }}" />
        </GridLayout>
    </ListView.itemTemplate>
</ListView>"},{"order":18,"type":"subheading","text":"Profiling and Monitoring Memory"},{"order":19,"type":"paragraph","text":"Use native profiling tools such as Android Studio Profiler and Xcode Instruments to monitor memory allocations, heap sizes, and CPU spikes. You can also manually trigger garbage collection during development or testing phases using platform-specific APIs if supported by the engine."}]
